/*
 * fake_tag_catalog_type.h — one simulated tag and what reading it must give
 * (test/fake/fake_tag_catalog.h, generated by scripts/gen_nfc_vectors.py).
 * Shared by the host tests and the emulator test image's transport.
 */
#pragma once

#include <stdbool.h>
#include <stdint.h>
#include "fake_pn532.h"
#include "stark_err.h"

typedef struct {
    const char *label;
    fake_tag_t tag;
    int vanish_after;     /* exchanges before the tag leaves; -1: it stays */
    const char *tech;     /* nfc_tech_name() of the identification */
    stark_err_t read_err; /* how the NDEF read ends */
    bool ndef_present;
    bool writable;
    uint16_t capacity; /* CC data-area bytes */
    const uint8_t *ndef;
    uint16_t ndef_len;
} fake_catalog_entry_t;
